      SUBROUTINE DECEXPC---- DECODE A PARAMETER EXPRESSIONC-----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'ICODE.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'ISEEDX.CIN'      INCLUDE 'NUMREP.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'STACK.CIN'      INCLUDE 'SVALUE.CIN'C-----------------------------------------------------------------------      PARAMETER       (NFUN = 10)      CHARACTER*15    KFUN(NFUN), KPARA, SYMBOL(NSYM)      CHARACTER*15    KNAME      LOGICAL         FLAG, HELEM      EQUIVALENCE     (IVSAV,VSAV), (FAKE,LAKE)C-----------------------------------------------------------------------      DATA KFUN(1)      / 'NEG     ' /      DATA KFUN(2)      / 'SQRT    ' /      DATA KFUN(3)      / 'LOG     ' /      DATA KFUN(4)      / 'EXP     ' /      DATA KFUN(5)      / 'SIN     ' /      DATA KFUN(6)      / 'COS     ' /      DATA KFUN(7)      / 'SINH    ' /      DATA KFUN(8)      / 'COSH    ' /      DATA KFUN(9)      / 'ASIN    ' /      DATA KFUN(10)     / 'ACOS    ' /C-----------------------------------------------------------------------      DATA SYMBOL(1)    / 'PI      ' /      DATA SYMBOL(2)    / 'TWOPI   ' /      DATA SYMBOL(3)    / 'DEGRAD  ' /      DATA SYMBOL(4)    / 'RADDEG  ' /      DATA SYMBOL(5)    / 'E       ' /      DATA SYMBOL(6)    / 'EMASS   ' /      DATA SYMBOL(7)    / 'PMASS   ' /      DATA SYMBOL(8)    / 'CLIGHT  ' /      DATA SYMBOL(9)    / 'MTOIN   ' /      DATA SYMBOL(10)   / 'INTOM   ' /C-----------------------------------------------------------------------      ERROR = .FALSE.CC---- CLEAR STACKC      LEV = 1      IOPER = 0      IOP(1) = 0CC---- EXPRESSION -------------------------------------------------------C      CALL RDNEXT      IF (ENDFIL) GO TO 700CC---- LEFT PARENTHESIS?C      IF (ITEM .EQ. '(') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 10      ENDIFCC---- UNARY "+" OR "-"?C  100 IF (ITEM .EQ. '+') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700      ELSE IF (ITEM .EQ. '-') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 12      ENDIFCC---- FACTOR OR TERM ---------------------------------------------------C---- EXPRESSION IN BRACKETS?C  200 IF (ITEM .EQ. '(') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 10        GO TO 100CC---- FUNCTION OR PARAMETER NAME?C      ELSE IF (INDEX(ALPHA,ITEM) .NE. 0) THEN        CALL RDWORD(KNAME,LNAME)CC---- FUNCTION?C        CALL RDNEXT        IF (ENDFIL) GO TO 700        IF (ITEM .EQ. '(') THEN          CALL RDLOOK(KNAME,LNAME,KFUN,1,NFUN,IFUN)          IF (IFUN .EQ. 0) THEN            CALL RDFAIL            WRITE (NOUT,910) KNAME(1:LNAME)            GO TO 800          ENDIF          CALL RDNEXT          IF (ENDFIL) GO TO 700          LEV = LEV + 1          IOP(LEV) = IFUN + 11          LEV = LEV + 1          IOP(LEV) = 10          GO TO 100CC---- ELEMENT PARAMETER?C        ELSE IF (ITEM .EQ. '[') THEN          CALL FNDLAB(KNAME,NELMN)          IF (NELMN .EQ. 0) THEN            NWORD = 2            LAKE = 55            DATUM(1) = FAKE            LABLE = KNAME            CALL ELSTOR            IVAL(LEV) = ISTOR(NEL) + 1            IREF(LEV) = 100            IPDAT(IPARM) = 100          ENDIF          CALL RDNEXT          IF (ENDFIL) GO TO 700          CALL RDWORD(KPARA,LPARA)          IF (LPARA .EQ. 0) THEN            CALL RDFAIL            WRITE (NOUT,930)             GO TO 800          ENDIF          CALL RDNEXT          IF (ENDFIL) GO TO 700          CALL RDTEST(']',FLAG)          IF (FLAG) GO TO 800          IF (NELMN .NE. 0) THEN            IST = ISTOR(NELMN)            NTYPE = IDATA(IST)            CALL RDPARS(KPARA,LPARA,IEP)          ELSE            IEP = 0          ENDIF          IF (IEP .EQ. 0) THEN            NWORD = 2            LAKE = 56            DATUM(1) = FAKE            LABLE = KPARA            CALL ELSTOR            IVAL(LEV) = ISTOR(NEL) + 1            IREF(LEV) = 100          ELSE            CALL 	SKETCH(NELMN)            IVAL(LEV) = IST + IPTOJ(IEP)            IREF(LEV) = 100          ENDIF          LAKE = IVAL(LEV)          PDATA(IPARM) = FAKE          IPDAT(IPARM) = 100CC---- GLOBAL PARAMETERC        ELSE          CALL RDBACK          HELEM = .FALSE.          IF ((NTYPE .EQ. 10 .AND. IPARM .EQ. 5)     1      .OR. NTYPE .EQ. 33 .OR. NTYPE .EQ. 38     2      .OR. NTYPE .EQ. 50 .OR. NTYPE .EQ. 51 .OR. NTYPE .EQ. 52)     3      HELEM = .TRUE.          IF (.NOT. HELEM) THEN            CALL FNDELM(KNAME,NVAL,30)            IF (NVAL .NE. 0) THEN              IVAL(LEV) = ISTOR(NVAL) + 1              IREF(LEV) = 100              IPDAT(IPARM) = 100              GO TO 280            ENDIF            CALL FNDNAM(KNAME,LNAME,INAME)            IF (INAME .NE. 0) THEN              CALL FITDEF              GO TO 280            ENDIF            CALL FNDELM(KNAME,NNAME,33)            IF (NNAME .NE. 0) THEN              INAME = ISTOR(NNAME-1) + 1              IVAL(LEV) = INAME              IREF(LEV) = 100              IPDAT(IPARM) = 100              GO TO 280            ENDIF            CALL RDLOOK(KNAME,LNAME,SYMBOL,1,NSYM,ISYM)            IF (ISYM .NE. 0) THEN              VALUE = SVALUE(ISYM)              CALL PARCON(IVAL(LEV),VALUE)              IREF(LEV) = 100              GO TO 280            ENDIF            CALL FNDELM(KNAME,NVAL,49)            IF (NVAL .NE. 0) THEN              IVAL(LEV) = ISTOR(NVAL) + 1              IREF(LEV) = 100              IPDAT(IPARM) = 100              GO TO 280            ENDIF            NWORD = 2            LAKE = 49            DATUM(1) = FAKE            DATUM(2) = 0.0            LABLE = KNAME            CALL ELSTOR            LABLE = ' '            IVAL(LEV) = ISTOR(NEL) + 1            IREF(LEV) = 100            IPDAT(IPARM) = 100            GO TO 280          ELSE            CALL FNDNAM(KNAME,LNAME,INAME)            IF (INAME .NE. 0) THEN              CALL FITDEF              GO TO 250            ENDIF            CALL FNDELM(KNAME,NNAME,33)            IF (NNAME .NE. 0) THEN              INAME = ISTOR(NNAME-1) + 1              ICODE = 9              JCODE = INAME              IF (INAME .EQ. 0) GO TO 250              IVAL(LEV) = INAME              IREF(LEV) = 100              IPTYP(IPARM) = 3              GO TO 250            ENDIF            CALL FNDELM(KNAME,NVAL,30)            IF (NVAL .NE. 0) THEN              IVAL(LEV) = ISTOR(NVAL) + 1              IREF(LEV) = 100              IPDAT(IPARM) = 100              GO TO 250            ENDIF            CALL RDLOOK(KNAME,LNAME,SYMBOL,1,NSYM,ISYM)            IF (ISYM .NE. 0) THEN              VALUE = SVALUE(ISYM)              CALL PARCON(IVAL(LEV),VALUE)              IREF(LEV) = 100              GO TO 250            ENDIFC  250       IF (IVAL(LEV) .EQ. 0) THEN              CALL FNDELM(KNAME,NVAL,30)              IVAL(LEV) = ISTOR(NVAL) + 1              IREF(LEV) = 100              IPDAT(IPARM) = 100            ENDIF          ENDIF  280     LAKE = IVAL(LEV)          PDATA(IPARM) = FAKE          IPDAT(IPARM) = IREF(LEV)        ENDIFCC---- NUMERIC VALUE?C      ELSE IF (INDEX('0123456789.',ITEM) .NE. 0) THEN        CALL RDNUMB(VALUE,IVALUE,FLAG)        IF (ENDFIL) GO TO 700         IF (FLAG) GO TO 800        IF (IOP(LEV) .EQ. 12) THEN          VALUE = - VALUE          LEV = LEV - 1        ENDIF        IF (INDS .EQ. 0 .OR. INSERT) THEN          IF (NTYPE .EQ. 16 .AND. IPARM .EQ. 17) THEN            IVSAV = IVALUE            VALUE = VSAV            CALL SEEDIT          ENDIF          CALL PARCON(IVAL(LEV),VALUE)          IREF(LEV) = 100        ELSE          IF (NTYPE .EQ. 16 .AND. IPARM .EQ. 17) THEN            LAKE = IVALUE            PDATA(IPARM) = FAKE          ELSE            PDATA(IPARM) = VALUE          ENDIF          IPTYP(IPARM) = 1        ENDIFCC---- ANYTHING ELSEC      ELSE        CALL RDFAIL        WRITE (NOUT,950)        GO TO 800      ENDIFCC---- UNSTACK UNARY OPERATORSC  300 IF (IOP(LEV) .GT. 10) CALL OPDEFCC---- UNSTACK MULTIPLY OPERATORSC      IF (IOP(LEV) .EQ. 3 .OR. IOP(LEV) .EQ. 4) CALL OPDEFCC---- TEST FOR MULTIPLY OPERATORSC      CALL RDNEXT      IF (ENDFIL) GO TO 700      IF (ITEM .EQ. '*') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 3        GO TO 200      ELSE IF (ITEM .EQ. '/') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 4        GO TO 200      ENDIFCC---- UNSTACK ADDING OPERATORSC      IF (IOP(LEV) .EQ. 1 .OR. IOP(LEV) .EQ. 2) CALL OPDEFCC---- TEST FOR ADDING OPERATORSC      IF (ITEM .EQ. '+') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 1        GO TO 200      ELSE IF (ITEM .EQ. '-') THEN        CALL RDNEXT        IF (ENDFIL) GO TO 700        LEV = LEV + 1        IOP(LEV) = 2        GO TO 200      ENDIFCC---- UNSTACK PARENTHESESC      IF (LEV .NE. 1) THEN        IF (ITEM .EQ. ')') THEN          IF (LEV .GE. 2) THEN            IF (IOP(LEV) .EQ. 10 .AND. IOP(LEV-1) .GT. 10) THEN              IOPT = IOP(LEV)              IOP(LEV) = IOP(LEV-1)              IOP(LEV-1) = IOPT              CALL OPDEF            ENDIF          ENDIF          LEV = LEV - 1          IVAL(LEV) = IVAL(LEV+1)          IREF(LEV) = IREF(LEV+1)          GO TO 300        ELSE          CALL RDFAIL          WRITE (NOUT,960)          GO TO 800        ENDIF      ELSE IF (ITEM .EQ. ')') THEN        CALL RDFAIL        WRITE (NOUT,970)        GO TO 800      ENDIFCC---- DISCARD UNNEEDED TEMPORARYC      CALL RDBACK  700 GO TO 900CC---- ERROR EXIT --- LEAVE PARAMETER UNDEFINEDC  800 IPTYP(IPARM) = -1      PDATA(IPARM) = 0.0      ERROR = .TRUE.  900 CONTINUE      RETURNC-----------------------------------------------------------------------  910 FORMAT (' *** ERROR *** UNKNOWN FUNCTION "',A,'"'/' ')  930 FORMAT (' *** ERROR *** PARAMETER KEYWORD EXPECTED'/' ')  940 FORMAT (' *** ERROR *** UNKNOWN ELEMENT PARAMETER "',A,'[',A,']"'/     +       ' ')  950 FORMAT (' *** ERROR *** OPERAND MUST BE NUMBER, PARAMETER NAME,',     +       ' FUNCTION CALL, OR EXPRESSION IN "()"'/' ')  960 FORMAT (' *** ERROR *** RIGHT PARENTHESIS MISSING'/' ')  970 FORMAT (' *** ERROR *** UNBALANCED RIGHT PARENTHESIS'/' ')  980 FORMAT (' *** ERROR *** UNKNOWN PARAMETER "',A,'"'/' ')C-----------------------------------------------------------------------      END